[ExtensionOf(tableStr(smmBusRelSalesDistrictGroup))]
final class AVAsmmBusRelSalesDistrictGroupDbt_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_id">smmSalesDistrictId</param>
/// <param name = "_forUpdate">Boolean</param>
/// <returns>smmBusRelSalesDistrictGroup</returns>
public static smmBusRelSalesDistrictGroup avaFind(  smmSalesDistrictId _id,
                                                    boolean            _forUpdate = false)
{
    smmBusRelSalesDistrictGroup record;

    record.selectForUpdate(_forUpdate);

    if(_id)
    {
        select firstonly record
        index hint SalesDistrictIdx
        where record.SalesDistrictId == _id;
    }

    return record;
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_id">smmSalesDistrictId</param>
/// <param name = "_dataAreaId">DataAreaId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>smmBusRelSalesDistrictGroup</returns>

public static smmBusRelSalesDistrictGroup avaFindDataAreaId(smmSalesDistrictId  _id,
                                                            DataAreaId          _dataAreaId,
                                                            boolean             _forUpdate = false)
{
    smmBusRelSalesDistrictGroup record;
    container                   masterCompany;

    record.selectForUpdate(_forUpdate);

    if(_id && _dataAreaId)
    {
        masterCompany = conIns(masterCompany, 1, _dataAreaId);
        select firstonly crosscompany : masterCompany record
        index hint SalesDistrictIdx
        where record.SalesDistrictId == _id;
    }

    return record;
}
